"""Build a standalone visual overview while retaining the complete original Markdown."""
from pathlib import Path
import base64,html,re,json,hashlib
ROOT=Path(__file__).resolve().parents[2]
SOURCE=ROOT/'docs/参赛提交说明-新增补充版本.md'
OUT=SOURCE.with_suffix('.html')
source=SOURCE.read_text(); original_hash=hashlib.sha256(SOURCE.read_bytes()).hexdigest()
e=html.escape

def asset(path):
 p=ROOT/path
 return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()

def plain(s):
 s=re.sub(r'\\([.+_&-])',r'\1',s)
 return re.sub(r'\*{1,2}','',s).strip()

def paragraph(title):
 blocks=source.split('\n\n')
 for i,b in enumerate(blocks):
  if plain(re.sub(r'^#+\s*','',b))==title:
   return plain(blocks[i+1])
 raise ValueError(title)

def flow(items,cls=''):
 return '<ol class="flow '+cls+'">'+''.join('<li><span class="number">'+str(i+1).zfill(2)+'</span><h3>'+e(t)+'</h3><p>'+e(d)+'</p></li>' for i,(t,d) in enumerate(items))+'</ol>'

def section(id,n,title,desc,body):
 return '<section id="'+id+'" class="section"><div class="section-head"><span class="eyebrow">'+n+'</span><h2>'+title+'</h2><p>'+desc+'</p></div>'+body+'</section>'

