js='''const modal=document.querySelector('dialog'),zoomImage=modal.querySelector('img');function openImage(img){zoomImage.src=img.src;zoomImage.alt=img.alt;zoomImage.classList.remove('zoomed');modal.showModal()}document.querySelectorAll('[data-zoom]').forEach(b=>b.addEventListener('click',()=>openImage(b.querySelector('img'))));document.querySelector('[data-zoom-main]').onclick=()=>openImage(document.querySelector('.architecture img'));modal.querySelector('button').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});zoomImage.onclick=()=>zoomImage.classList.toggle('zoomed');const info={service:'Service Ontology：连接产品、订单、知识与证据，确定当前处理对象及资料适用范围。',decision:'Decision Ontology：结合案件状态和服务规则计算允许与禁止动作；模型表达不直接授予业务权限。'};document.querySelectorAll('[data-info]').forEach(n=>{const show=()=>{document.querySelector('#ontology-info').textContent=info[n.dataset.info]};n.onclick=show;n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}}});document.querySelectorAll('[data-branch]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.branch-row').forEach(x=>x.classList.remove('selected'));b.closest('.branch-row').classList.add('selected');document.querySelector('#branch-status').textContent=b.closest('.branch-row').innerText.replaceAll('\\n',' ')});document.querySelector('#back-top').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});document.addEventListener('scroll',()=>{const h=document.documentElement;document.querySelector('.progress').style.width=(h.scrollTop/Math.max(1,h.scrollHeight-h.clientHeight)*100)+'%'},{passive:true});document.querySelector('#download-md').onclick=()=>{const source=atob(document.querySelector('#source-md').textContent.trim()),bytes=Uint8Array.from(source,c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='参赛提交说明-新增补充版本.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};'''
page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OntoCare · 项目架构与服务闭环</title><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 32 32%27%3E%3Crect width=%2732%27 height=%2732%27 rx=%277%27 fill=%27%23081720%27/%3E%3Ccircle cx=%2716%27 cy=%2716%27 r=%278%27 fill=%27none%27 stroke=%27%2317cbdb%27 stroke-width=%274%27/%3E%3C/svg%3E"><meta name="description" content="OntoCare 项目可视化导读：核心技术架构、双本体、服务流程、改进闭环与经营归因。"><style>'''+css+'''</style></head><body><header><div class="top"><a class="brand" href="#">OntoCare</a><nav aria-label="页面导航"><a href="#architecture">核心架构</a><a href="#pipeline">服务链路</a><a href="#evolution">改进闭环</a><a href="#attribution">经营归因</a><a href="#original">完整原文</a><a href="https://github.com/jiangenjing/anker-OntoCare">GitHub ↗</a></nav></div><div class="progress"></div></header><div class="hero"><div class="hero-inner"><div><img class="hero-logo" src="'''+logo+'''" alt="ANKER"><span class="eyebrow">ONTOCARE · ANKER HACKATHON</span><h1>从一次求助，<br>到<em>有依据的下一步</em>。</h1><p>基于本体论与自进化闭环的经营归因智能客服系统</p><p>双本体组织证据与规则，评测连接失败与改进，工单集合形成经营核查线索。</p><div class="hero-actions"><a class="primary" href="#architecture">先看核心技术架构 ↓</a><a href="#product">查看双端功能</a><a href="#original">保留原文</a></div></div><div class="hero-map"><div><span class="idx">01</span><div><strong>Service + Decision</strong><small>业务对象 · 证据关系 · 动作边界</small></div></div><div class="middle"><span class="idx">02</span><div><strong>Bad Case → 审核 → 回归</strong><small>发现失败 · 靶向修正 · 保留轨迹</small></div></div><div class="last"><span class="idx">03</span><div><strong>工单集合 → 经营核查</strong><small>源表行号 · 规则 ID · 行动建议</small></div></div></div></div></div><main>'''+''.join(sections)+'''</main><footer>OntoCare 本体队 · 图解阅读版 · 原文与图示分层展示 · 无需外部脚本库</footer><button id="back-top" aria-label="返回顶部">↑</button><dialog aria-label="图片放大查看"><div class="dialogbar"><span>OntoCare · 图片查看</span><button aria-label="关闭图片">关闭 ×</button></div><div class="image-viewport"><img alt=""></div><p class="dialoghint">点击图片切换 2 倍放大；可滚动查看，按 Esc 关闭。</p></dialog><script id="source-md" type="application/octet-stream">'''+base64.b64encode(SOURCE.read_bytes()).decode()+'''</script><script>'''+js+'</script></body></html>'
# Correct relative deck navigation from docs/ and retain deterministic build.
page=page.replace('../../presentation/index.html','../presentation/index.html')
OUT.write_text(page)
assert hashlib.sha256(SOURCE.read_bytes()).hexdigest()==original_hash
assert base64.b64decode(re.search(r'<script id="source-md"[^>]*>(.*?)</script>',page,re.S)[1])==SOURCE.read_bytes()
print(json.dumps({'html':str(OUT),'sections':len(sections),'bytes':OUT.stat().st_size,'source_sha256':original_hash,'inline_images':4,'source_preserved':True},ensure_ascii=False))
